-- FengXue — consolidated dictionary seed (schema + Band A words + example sentences)
-- Generated by scripts/import-dictionary-pdf.js + scripts/match-vnxpats-examples.js
-- Example sentences sourced from vnxpats.com's "1000 từ vựng Band A TOCFL" page (876/876
-- matched), with a handful of hand-authored fallbacks for words vnxpats didn't have.
-- Safe to run even if some/all of this was already applied — every statement is idempotent.
-- Paste this whole file into the Supabase Dashboard SQL Editor and click Run once.

-- ============================================================
-- SCHEMA: dictionary_words, dictionary_progress, practice_sessions
-- ============================================================
CREATE TABLE IF NOT EXISTS public.dictionary_words (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    band TEXT NOT NULL,
    level TEXT NOT NULL,
    hanzi TEXT NOT NULL,
    pinyin TEXT NOT NULL,
    vietnamese TEXT NOT NULL,
    pos TEXT,
    order_index INTEGER DEFAULT 0,
    example_hanzi TEXT,
    example_pinyin TEXT,
    example_vietnamese TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(level, hanzi, pinyin, vietnamese)
);

ALTER TABLE public.dictionary_words ADD COLUMN IF NOT EXISTS example_hanzi TEXT;
ALTER TABLE public.dictionary_words ADD COLUMN IF NOT EXISTS example_pinyin TEXT;
ALTER TABLE public.dictionary_words ADD COLUMN IF NOT EXISTS example_vietnamese TEXT;

ALTER TABLE public.dictionary_words ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Anyone authenticated can read dictionary" ON public.dictionary_words;
CREATE POLICY "Anyone authenticated can read dictionary"
    ON public.dictionary_words FOR SELECT
    TO authenticated
    USING (true);

CREATE TABLE IF NOT EXISTS public.dictionary_progress (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    level TEXT NOT NULL,
    word_order UUID[] NOT NULL DEFAULT '{}',
    current_index INTEGER NOT NULL DEFAULT 0,
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(user_id, level)
);

ALTER TABLE public.dictionary_progress ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can manage own dictionary progress" ON public.dictionary_progress;
CREATE POLICY "Users can manage own dictionary progress"
    ON public.dictionary_progress FOR ALL
    USING (auth.uid() = user_id)
    WITH CHECK (auth.uid() = user_id);

CREATE TABLE IF NOT EXISTS public.practice_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    level TEXT NOT NULL,
    total_questions INTEGER NOT NULL,
    correct_count INTEGER NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.practice_sessions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can manage own practice sessions" ON public.practice_sessions;
CREATE POLICY "Users can manage own practice sessions"
    ON public.practice_sessions FOR ALL
    USING (auth.uid() = user_id)
    WITH CHECK (auth.uid() = user_id);

